def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if n * 2 > last:
        result = 1
    else:
        result = count_sequences(n, last - n, memo) + count_sequences(n, last - n * 2, memo)
    memo[last] = result
    return result
