    for participant, statement_list in statements.items():
        # Check if the participant is a liar
        if participant in liar_count:
            # If the participant is a liar, check if their statement is consistent with the scenario
            for statement in statement_list:
                if scenario in statement:
                    # If the statement is consistent with the scenario, return True
